script:
export const meta = {
  name: 'review_loop',
  description: 'Actor-Critic review->fix->re-review loop with focused per-round tests, one final full validation, chunked fan-out, and bounded convergence',
  phases: [{ title: 'Scope' }, { title: 'Converge' }, { title: 'Final Validation' }, { title: 'Report' }],
}

// ---- Config (overridable via args; CLI key=value arrive as strings) ----
const bounded = (v, d, min, max) => { const n = Number(v); return Math.min(max, Math.max(min, Number.isFinite(n) ? n : d)) }
const boundedInt = (v, d, min, max) => Math.floor(bounded(v, d, min, max))
const consecutiveEmpty = 2
const scope = (args && args.scope) || (args && args._) || 'the current branch vs its merge-base with main, else staged, else HEAD'
const maxRounds = boundedInt(args && args.maxRounds, 3, 1, 5)
const reviewers = boundedInt(args && args.reviewers, 2, 1, 3)
const threshold = bounded(args && args.threshold, 0.5, 0, 1)
const chunkTarget = boundedInt(args && args.chunkTargetLines, 400, 1, 10000)
const maxChunks = boundedInt(args && args.maxChunks, 6, 1, 12)
const maxFindingsPerLane = boundedInt(args && args.maxFindingsPerLane, 5, 1, 10)
const maxVerifyClaimsPerRound = boundedInt(args && args.maxVerifyClaimsPerRound, 8, 1, 16)
const focusedTestMaxCommands = boundedInt(args && args.focusedTestMaxCommands, 3, 1, 5)
const fixerTimeoutMs = boundedInt(args && args.fixerTimeoutMs, 900000, 60000, 1800000)
const focusedValidationTimeoutMs = boundedInt(args && args.focusedValidationTimeoutMs, 600000, 60000, 1800000)
const finalValidationTimeoutMs = boundedInt(args && args.finalValidationTimeoutMs, 1800000, 300000, 3600000)
let gate = (args && args.severityGate) || ['blocker', 'high']
if (typeof gate === 'string') gate = gate.split(',').map((s) => s.trim()).filter(Boolean)
const limits = { maxRounds, reviewers, threshold, chunkTargetLines: chunkTarget, maxChunks, maxFindingsPerLane,
  maxVerifyClaimsPerRound, focusedTestMaxCommands, fixerTimeoutMs, focusedValidationTimeoutMs, finalValidationTimeoutMs }

const findingSchema = {
  type: 'object',
  properties: { findings: { type: 'array', maxItems: maxFindingsPerLane, items: { type: 'object', properties: {
    id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'high', 'medium', 'suggestion'] },
    category: { type: 'string', enum: ['security', 'correctness', 'performance', 'maintainability'] },
    location: { type: 'string' }, description: { type: 'string' }, evidence: { type: 'string' },
    repro_test: { type: 'string' }, boundary_owner: { type: 'string', enum: ['current', 'server', 'external'] },
    confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
  }, required: ['id', 'severity', 'category', 'location', 'description', 'boundary_owner'],
  if: { properties: { severity: { enum: ['blocker', 'high'] } } }, then: { required: ['repro_test'] } } } },
  required: ['findings'],
}

const fixSchema = {
  type: 'object',
  properties: {
    summary: { type: 'string' },
    fixes: { type: 'array', items: { type: 'object', properties: {
      findingId: { type: 'string' }, location: { type: 'string' }, change: { type: 'string' },
      files: { type: 'array', items: { type: 'string' } },
      tests: { type: 'array', items: { type: 'string' } },
    }, required: ['findingId', 'location', 'change', 'files', 'tests'] } },
    focusedTestCommands: { type: 'array', items: { type: 'string' } },
  },
  required: ['summary', 'fixes', 'focusedTestCommands'],
}

const focusedValidationSchema = {
  type: 'object',
  properties: {
    applied: { type: 'boolean' },
    focusedTestsStatus: { type: 'string', enum: ['passed', 'failed', 'unavailable'] },
    commands: { type: 'array', items: { type: 'object', properties: {
      command: { type: 'string' }, status: { type: 'string', enum: ['passed', 'failed', 'not_run'] },
      purpose: { type: 'string' }, notes: { type: 'string' },
    }, required: ['command', 'status', 'purpose'] } },
    checkedFindingIds: { type: 'array', items: { type: 'string' } },
    changedFiles: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
  required: ['applied', 'focusedTestsStatus', 'commands', 'checkedFindingIds', 'changedFiles', 'notes'],
}

const finalValidationSchema = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['passed', 'failed', 'unavailable'] },
    commands: { type: 'array', items: { type: 'object', properties: {
      command: { type: 'string' }, status: { type: 'string', enum: ['passed', 'failed', 'not_run'] },
      purpose: { type: 'string' }, notes: { type: 'string' },
    }, required: ['command', 'status', 'purpose'] } },
    summary: { type: 'string' },
    failures: { type: 'array', items: { type: 'string' } },
  },
  required: ['status', 'commands', 'summary', 'failures'],
}

// Critic ids are non-deterministic across rounds, so category+location is the tight
// loop identity. The report key retains a description fingerprint to avoid merging
// different issues that happen to share a location.
const keyOf = (f) => (f.category || '?') + '|' + (f.location || '?')
const fp = (s) => { let h = 0; const str = String(s || ''); for (let i = 0; i < str.length; i++) { h = (h * 31 + str.charCodeAt(i)) | 0 } return h }
const reportKeyOf = (f) => keyOf(f) + '|' + fp(f.description)
const dedupBy = (arr, keyFn) => {
  const seen = {}
  const out = []
  for (const f of arr) { const k = keyFn(f); if (!seen[k]) { seen[k] = true; out.push(f) } }
  return out
}
const uniq = (arr) => {
  const seen = {}
  const out = []
  for (const value of arr || []) { const key = String(value); if (!seen[key]) { seen[key] = true; out.push(value) } }
  return out
}

// Shell-quote untrusted filenames before embedding them in a lane instruction.
const shq = (p) => "'" + String(p).replace(/'/g, "'\\''") + "'"
const laneNames = ['maintainability', 'correctness', 'security']
const laneCount = laneNames.length

// ---- Phase 1: resolve scope + deterministic per-file sizes, then pack bounded chunks ----
phase('Scope')
const scan = await agent(
  'Resolve review scope: ' + scope + '. Determine a single git diff command (for example "git diff main...HEAD", ' +
  '"git diff --staged", or "git show HEAD") WITHOUT file paths. Compute per-file and total added+removed line counts ' +
  'DETERMINISTICALLY from git numstat (for example `git diff --numstat <range>`); do not eyeball or estimate counts. ' +
  'Return diffCmd, files [{path, lineCount}], and totalLines.',
  { tier: 'small', label: 'scope + sizes', schema: { type: 'object', properties: {
      diffCmd: { type: 'string' },
      files: { type: 'array', items: { type: 'object', properties: { path: { type: 'string' }, lineCount: { type: 'number' } }, required: ['path', 'lineCount'] } },
      totalLines: { type: 'number' }
    }, required: ['diffCmd', 'files', 'totalLines'] } })
const safeDiffCmd = scan && typeof scan.diffCmd === 'string' && /^\s*git\s+(diff|show)\b/.test(scan.diffCmd) && !/[;&|`$<>\n\r]/.test(scan.diffCmd)
if (!scan || !safeDiffCmd || !Array.isArray(scan.files)) {
  return { verdict: 'ABORTED - could not resolve a safe scope/diff', roundsRun: 0, chunks: 0, oversizedFiles: [], limits,
           totalAddressed: 0, totalResolved: 0, totalFixed: 0, unresolved: [], unverified: [], disputed: [], tracked: [],
           verificationOverflow: [], verificationOverflowCount: 0, unresolvedVerificationOverflow: [], unresolvedVerificationOverflowCount: 0,
           fixerFailure: null, terminationReason: 'scope-resolution-failed',
           trajectory: [], fixLog: [], finalValidation: { status: 'skipped', reason: 'scope resolution failed', commands: [], summary: '', failures: [] },
           report: 'Scope agent returned no usable file list or returned an unsafe diff command.' }
}

const perChunk = Math.max(chunkTarget, Math.ceil((scan.totalLines || 1) / maxChunks))
const chunks = []
let cur = [], curLines = 0
for (const f of scan.files) {
  if (cur.length && curLines + f.lineCount > perChunk) { chunks.push(cur); cur = []; curLines = 0 }
  cur.push(f); curLines += f.lineCount
}
if (cur.length) chunks.push(cur)
if (chunks.length > maxChunks) {
  const merged = chunks.slice(0, maxChunks - 1)
  merged.push(chunks.slice(maxChunks - 1).flat())
  chunks.length = 0
  for (const c of merged) chunks.push(c)
}
const oversizedFiles = scan.files.filter((f) => f.lineCount > perChunk).map((f) => f.path)
const chunkSummary = chunks.map((chunk, i) => ({
  chunk: i + 1,
  files: chunk.map((f) => f.path),
  lines: chunk.reduce((n, f) => n + f.lineCount, 0),
}))
log('scope: ' + scan.files.length + ' files, ' + scan.totalLines + ' lines -> ' + chunks.length + ' chunk(s) of ~' + perChunk + ' lines')

const RULES =
  ' RULES: Comment ONLY on the files in this chunk plus at most one hop of direct dependencies. Flag issues; do NOT rewrite code. ' +
  'Severity blocker/high = crashes, security, logic bugs, measurable perf/arch regressions; medium/suggestion = style, micro-opts, speculative edge cases. ' +
  'Set boundary_owner=current only if the fix belongs in THIS diff. For every blocker/high include a concrete repro_test that fails on current behavior. Quote evidence. ' +
  'Return only your highest-priority actionable findings, up to ' + maxFindingsPerLane + ' total.'

const laneOnChunk = (persona, tier, paths, tag) =>
  agent(persona + ' Obtain this chunk\'s diff by running: ' + scan.diffCmd + ' -- ' + paths.map(shq).join(' ') +
        '\nReview only those files (+ one hop).' + RULES,
        { tier, label: tag, schema: findingSchema })

// ---- Phase 2: bounded Actor-Critic convergence loop ----
phase('Converge')
let lastSurvivors = []
let roundsRun = 0
const tracked = []
const unverified = []
const disputed = []
const verificationOverflow = []
const addressed = []
const fixLog = []
const trajectory = []
let convergedDry = 0
let verificationClaims = 0
let verificationDedupSavings = 0
let fixerFailure = null
let terminationReason = 'round-cap'
const severityRank = { blocker: 0, high: 1 }
const confidenceRank = { high: 0, medium: 1, low: 2 }
const prioritizeFindings = (a, b) => {
  const severity = (severityRank[a.severity] ?? 2) - (severityRank[b.severity] ?? 2)
  if (severity) return severity
  const confidence = (confidenceRank[a.confidence] ?? 3) - (confidenceRank[b.confidence] ?? 3)
  if (confidence) return confidence
  const aKey = keyOf(a)
  const bKey = keyOf(b)
  return aKey < bKey ? -1 : (aKey > bKey ? 1 : 0)
}
const resolveOverflow = (finding, resolution, round) => {
  const key = keyOf(finding)
  for (const entry of verificationOverflow) {
    if (entry.status === 'pending' && entry.key === key) {
      entry.status = resolution
      entry.resolutionRound = round
    }
  }
}

for (let r = 0; r < maxRounds && convergedDry < consecutiveEmpty && !fixerFailure; r++) {
  roundsRun = r + 1
  const totalLanes = chunks.length * laneCount
  log('round ' + roundsRun + ' start: ' + chunks.length + ' chunk(s), ' + totalLanes + ' critic lane(s)')
  const perChunkResults = await parallel(chunks.map((chunk, ci) => async () => {
    const paths = chunk.map((f) => f.path)
    const lanes = await parallel([
      () => laneOnChunk('Read the skill file at ~/.agents/skills/thermo-nuclear-code-quality-review/SKILL.md (expand ~ to your home dir) and apply it as a MAINTAINABILITY critic.',
                        'criticBig', paths, 'maint c' + ci + ' r' + roundsRun),
      () => laneOnChunk('You are a CORRECTNESS critic: trace critical paths; logic bugs, missing authz, boundary/edge errors.',
                        'criticBig', paths, 'correct c' + ci + ' r' + roundsRun),
      () => laneOnChunk('You are a SECURITY critic: injection, secrets, authz, unsafe handling of untrusted input.',
                        'criticBig', paths, 'sec c' + ci + ' r' + roundsRun),
    ])
    const failedLanes = laneNames.filter((_name, i) => !lanes[i])
    return { chunk: ci + 1, paths, lanes, failedLanes, findings: lanes.filter(Boolean).flatMap((l) => (l && l.findings) || []) }
  }))
  const all = perChunkResults.flatMap((x) => x.findings)
  const lanesOk = perChunkResults.reduce((n, x) => n + x.lanes.filter(Boolean).length, 0)
  const missingCoverage = perChunkResults.flatMap((x) => x.failedLanes.map((lane) => ({ chunk: x.chunk, lane, files: x.paths })))
  log('round ' + roundsRun + ' critic barrier complete: ' + missingCoverage.length + ' missing lane(s)')

  const gatedRaw = []
  for (const f of all) {
    if (gate.indexOf(f.severity) >= 0 && f.boundary_owner === 'current') gatedRaw.push(f)
    else tracked.push(f)
  }
  // Multiple critic lanes often report the same location. Verify it once per round,
  // then prioritize and bound verifier work deterministically.
  const gated = dedupBy(gatedRaw, keyOf).sort(prioritizeFindings)
  verificationDedupSavings += gatedRaw.length - gated.length
  const verificationQueue = gated.slice(0, maxVerifyClaimsPerRound)
  const overflowFindings = gated.slice(maxVerifyClaimsPerRound)
  for (const finding of overflowFindings) {
    verificationOverflow.push({ round: roundsRun, key: keyOf(finding), status: 'pending', finding })
  }

  if (!gated.length) {
    trajectory.push({ round: roundsRun, lanesOk, totalLanes, missingCoverage, findings: all.length,
      gatedRaw: gatedRaw.length, gated: 0, deduplicatedBeforeVerify: gatedRaw.length,
      verificationClaims: 0, verificationOverflowCount: 0, verificationOverflow: [],
      verified: 0, refuted: 0, disputed: 0, unverified: 0, fixesRequested: 0,
      fixes: [], changedFiles: [], testsChanged: [], focusedValidation: { status: 'not_run', commands: [], notes: 'No verified fixes this round.' } })
    lastSurvivors = []
    convergedDry++
    if (convergedDry >= consecutiveEmpty) terminationReason = 'consecutive-clean-rounds'
    continue
  }

  verificationClaims += verificationQueue.length
  log('round ' + roundsRun + ' verification start: ' + verificationQueue.length + ' claim(s), ' + (verificationQueue.length * reviewers) + ' vote(s)')
  const checks = await parallel(verificationQueue.map((f) => () =>
    verify('Category ' + f.category + ' at ' + f.location + ': ' + f.description +
           '\nClaimed repro: ' + (f.repro_test || '(none)') +
           '\nREAL only if the repro would truly fail on current behavior and the fix belongs in this diff.',
           { reviewers, threshold, lens: [f.category, 'is this edge case already implicitly handled?'] })))
  const survivors = []
  let unverifiedThisRound = 0
  let disputedThisRound = 0
  let refutedThisRound = 0
  verificationQueue.forEach((f, i) => {
    const c = checks[i]
    const covered = c && typeof c.total === 'number' ? c.total : 0
    if (!c || covered < reviewers) {
      unverified.push(f)
      unverifiedThisRound++
      log('Verification incomplete for ' + keyOf(f) + ' in round ' + roundsRun + ' (covered ' + covered + '/' + reviewers + '); escalating.')
    } else if (c.real) {
      survivors.push(f)
      addressed.push(f)
    } else if ((c.realCount || 0) > 0) {
      disputed.push(f)
      disputedThisRound++
      log('Finding ' + keyOf(f) + ' disputed in round ' + roundsRun + '; escalating.')
    } else {
      refutedThisRound++
      resolveOverflow(f, 'refuted', roundsRun)
    }
  })
  lastSurvivors = survivors
  log('round ' + roundsRun + ' verification complete: ' + survivors.length + ' survivor(s), ' + overflowFindings.length + ' overflow claim(s)')

  if (!survivors.length) {
    trajectory.push({ round: roundsRun, lanesOk, totalLanes, missingCoverage, findings: all.length,
      gatedRaw: gatedRaw.length, gated: gated.length, deduplicatedBeforeVerify: gatedRaw.length - gated.length,
      verificationClaims: verificationQueue.length, verificationOverflowCount: overflowFindings.length, verificationOverflow: overflowFindings,
      verified: 0, refuted: refutedThisRound, disputed: disputedThisRound, unverified: unverifiedThisRound,
      fixesRequested: 0, fixes: [], changedFiles: [], testsChanged: [],
      focusedValidation: { status: 'not_run', commands: [], notes: 'No findings survived verification.' } })
    if (overflowFindings.length) convergedDry = 0
    else convergedDry++
    if (convergedDry >= consecutiveEmpty) terminationReason = 'consecutive-clean-rounds'
    continue
  }

  convergedDry = 0
  log('round ' + roundsRun + ' fixer start: ' + survivors.length + ' finding(s)')
  const fix = await agent(
    'You are the fixer. Apply MINIMAL fixes for ONLY these verified blockers, add a focused failing-before/passing-after test for each, ' +
    'and stay within the diff scope. Do not run the full test suite. Return: a concise summary; fixes with findingId, location, exact change, ' +
    'files, and tests added/updated; plus up to ' + focusedTestMaxCommands + ' narrow test commands that exercise only the changed behavior.\n\n' +
    JSON.stringify(survivors),
    { tier: 'fixerBig', label: 'fix r' + roundsRun, schema: fixSchema, retries: 0, timeoutMs: fixerTimeoutMs })

  if (!fix) {
    fixerFailure = {
      round: roundsRun,
      survivorFindings: survivors,
      state: 'failed-or-timed-out',
      timeoutOrFailure: true,
      partialWorkingTreeChangesMayExist: true,
    }
    log('round ' + roundsRun + ' fixer failure: result missing; partial working-tree changes may exist')
    log('round ' + roundsRun + ' focused validation start: read-only partial-change inspection')
    const inspection = await agent(
      'You are the focused validator. Work read-only: do not edit source or tests. The fixer failed or timed out and may have left partial working-tree changes. ' +
      'Inspect the working tree and run at most ' + focusedTestMaxCommands + ' narrow, safe commands only if useful. Report what appears to have landed, ' +
      'but do NOT classify the intended fix as successfully applied because the fixer call failed.\n\nFINDINGS:\n' + JSON.stringify(survivors),
      { tier: 'medium', label: 'validate focused failed fixer r' + roundsRun, schema: focusedValidationSchema,
        retries: 1, timeoutMs: focusedValidationTimeoutMs })
    log('round ' + roundsRun + ' focused validation end: ' + (inspection ? inspection.focusedTestsStatus : 'missing'))
    const changedFiles = uniq((inspection && inspection.changedFiles) || [])
    const testsChanged = []
    trajectory.push({ round: roundsRun, lanesOk, totalLanes, missingCoverage, findings: all.length,
      gatedRaw: gatedRaw.length, gated: gated.length, deduplicatedBeforeVerify: gatedRaw.length - gated.length,
      verificationClaims: verificationQueue.length, verificationOverflowCount: overflowFindings.length, verificationOverflow: overflowFindings,
      verified: survivors.length, refuted: refutedThisRound, disputed: disputedThisRound, unverified: unverifiedThisRound,
      fixesRequested: survivors.length, fixerFailure, fixes: [], changedFiles, testsChanged,
      focusedValidation: { status: 'unavailable', applied: null, commands: inspection && inspection.commands || [],
        notes: 'Fixer failed or timed out; validator inspection cannot confirm a successful fix.' } })
    fixLog.push({ round: roundsRun, findings: survivors, fixer: null, fixerFailure, focusedValidation: inspection,
      applied: null, focusedTestsStatus: 'unavailable', changedFiles, testsChanged,
      partialWorkingTreeChangesMayExist: true })
    terminationReason = 'fixer-failed-or-timed-out'
    break
  }

  const fixDetails = fix
  log('round ' + roundsRun + ' fixer end: structured result received')
  // Per-round validation is deliberately narrow. The full repository suite runs once,
  // only after the review reaches a complete convergence candidate.
  log('round ' + roundsRun + ' focused validation start')
  const validation = await agent(
    'You are the focused validator. Work read-only: do not edit source or tests. Independently inspect the working tree and confirm the intended fixes landed. ' +
    'Run at most ' + focusedTestMaxCommands + ' focused commands targeting only the changed test files, nearest test cases, or affected package. ' +
    'You may run file-local syntax/static checks. DO NOT run the full repository test suite, full build, full lint, or repo-wide typecheck in this round. ' +
    'Do not blindly execute fixer-suggested commands; inspect them first. If no narrow command exists, return focusedTestsStatus=unavailable rather than falling back to a full command.\n\n' +
    'FINDINGS:\n' + JSON.stringify(survivors) + '\n\nFIXER REPORT:\n' + JSON.stringify(fixDetails),
    { tier: 'medium', label: 'validate focused r' + roundsRun, schema: focusedValidationSchema,
      retries: 1, timeoutMs: focusedValidationTimeoutMs })
  log('round ' + roundsRun + ' focused validation end: ' + (validation ? validation.focusedTestsStatus : 'missing'))
  if (!validation) log('Focused validation returned null in round ' + roundsRun + '; fix landing/tests unconfirmed.')
  const applied = validation ? validation.applied : null
  const focusedTestsStatus = validation ? validation.focusedTestsStatus : 'unavailable'
  const focusedCommands = validation && Array.isArray(validation.commands) ? validation.commands : []
  const changedFiles = uniq((fixDetails.fixes || []).flatMap((f) => f.files || []).concat(validation && validation.changedFiles || []))
  const testsChanged = uniq((fixDetails.fixes || []).flatMap((f) => f.tests || []))
  if (applied === true && focusedTestsStatus === 'passed') {
    for (const finding of survivors) resolveOverflow(finding, 'fixed-and-focused-validated', roundsRun)
  }

  const roundRecord = { round: roundsRun, lanesOk, totalLanes, missingCoverage, findings: all.length,
    gatedRaw: gatedRaw.length, gated: gated.length, deduplicatedBeforeVerify: gatedRaw.length - gated.length,
    verificationClaims: verificationQueue.length, verificationOverflowCount: overflowFindings.length, verificationOverflow: overflowFindings,
    verified: survivors.length, refuted: refutedThisRound, disputed: disputedThisRound, unverified: unverifiedThisRound,
    fixesRequested: survivors.length, fixSummary: fixDetails.summary, fixes: fixDetails.fixes || [], changedFiles, testsChanged,
    focusedValidation: { status: focusedTestsStatus, applied, commands: focusedCommands, notes: validation && validation.notes || '' } }
  trajectory.push(roundRecord)
  fixLog.push({ round: roundsRun, findings: survivors, fixer: fixDetails, focusedValidation: validation,
    applied, focusedTestsStatus, changedFiles, testsChanged, partialWorkingTreeChangesMayExist: false })
}

if (fixerFailure) terminationReason = 'fixer-failed-or-timed-out'
else if (convergedDry >= consecutiveEmpty) terminationReason = 'consecutive-clean-rounds'
else terminationReason = 'round-cap'
log('termination: ' + terminationReason)
// ---- Phase 3: run the expensive full suite once, only after review convergence ----
phase('Final Validation')
const trackedUnique = dedupBy(tracked, reportKeyOf)
const unverifiedUnique = dedupBy(unverified, reportKeyOf)
const disputedUnique = dedupBy(disputed, reportKeyOf)
const addressedUnique = dedupBy(addressed, keyOf)
const pendingVerificationOverflow = verificationOverflow.filter((entry) => entry.status === 'pending')
const totalAddressed = addressedUnique.length
const unresolvedKeys = {}
for (const f of lastSurvivors) unresolvedKeys[keyOf(f)] = true
for (const entry of pendingVerificationOverflow) unresolvedKeys[entry.key] = true
const resolvedKeys = {}
for (const e of fixLog) {
  if (e.applied === true && e.focusedTestsStatus === 'passed') {
    for (const f of (e.findings || [])) { const k = keyOf(f); if (!unresolvedKeys[k]) resolvedKeys[k] = true }
  }
}
const totalResolved = Object.keys(resolvedKeys).length
const terminal = trajectory.slice(-consecutiveEmpty)
const coverageComplete = terminal.length === consecutiveEmpty && terminal.every((t) => t.lanesOk === t.totalLanes)
const unconfirmedFixes = fixLog.filter((e) => e.applied !== true || e.focusedTestsStatus !== 'passed')
const converged = convergedDry >= consecutiveEmpty
const finalValidationEligible = !fixerFailure && lastSurvivors.length === 0 && converged && coverageComplete &&
  disputedUnique.length === 0 && unverifiedUnique.length === 0 && pendingVerificationOverflow.length === 0
let finalValidation = {
  status: 'skipped', commands: [], summary: 'Full validation skipped because the review did not reach a complete convergence candidate.', failures: [],
  reason: fixerFailure ? 'fixer-failed-or-timed-out' : (pendingVerificationOverflow.length ? 'verification-overflow' : 'not-converged'),
}
if (finalValidationEligible) {
  log('final validation start')
  const finalResult = await agent(
    'You are the final validator. The review loop reached a complete convergence candidate. Work read-only: do not edit source or tests. ' +
    'Discover the canonical repository-wide validation commands from project docs, package scripts, and CI. Run the FULL test suite now, once, ' +
    'plus any canonical full build/typecheck required to certify the repository. Avoid redundant command variants and do not rerun individual focused tests separately. ' +
    'Return every command and outcome, a concise summary, and concrete failures. If the complete validation cannot be run, return status=unavailable.\n\n' +
    'SCOPE:\n' + JSON.stringify({ scope, files: scan.files.map((f) => f.path) }) +
    '\n\nFIX ROUNDS:\n' + JSON.stringify(fixLog),
    { tier: 'medium', label: 'final validation', schema: finalValidationSchema,
      retries: 0, timeoutMs: finalValidationTimeoutMs })
  finalValidation = finalResult || {
    status: 'unavailable', commands: [], summary: 'Final validation returned no result.', failures: ['Missing final validation coverage.'], reason: 'validator-null',
  }
  log('final validation end: ' + finalValidation.status)
} else {
  log('final validation start: skipped (' + finalValidation.reason + ')')
  log('final validation end: skipped')
}

const verdict =
    fixerFailure ? 'INCONCLUSIVE - fixer failed or timed out; inspect partial working-tree changes'
  : (lastSurvivors.length > 0 && roundsRun >= maxRounds) ? 'STOPPED AT CAP - escalate to human'
  : (pendingVerificationOverflow.length > 0) ? ('INCONCLUSIVE - unresolved verification overflow (' + pendingVerificationOverflow.length + ' claim(s))')
  : (lastSurvivors.length === 0 && !converged) ? ('STOPPED AT CAP - did not reach ' + consecutiveEmpty + ' consecutive dry rounds; do not treat as clean')
  : (lastSurvivors.length === 0 && disputedUnique.length > 0) ? ('CONVERGED WITH DISPUTED FINDINGS - ' + disputedUnique.length + ' need human review')
  : (lastSurvivors.length === 0 && !coverageComplete) ? 'INCONCLUSIVE - incomplete critic coverage'
  : (lastSurvivors.length === 0 && unverifiedUnique.length > 0) ? ('CONVERGED WITH UNVERIFIED FINDINGS - ' + unverifiedUnique.length + ' need human review')
  : (lastSurvivors.length === 0 && unconfirmedFixes.length > 0) ? ('CONVERGED WITH UNCONFIRMED FOCUSED VALIDATION - ' + unconfirmedFixes.length + ' fix round(s) need review')
  : (lastSurvivors.length === 0 && finalValidation.status === 'failed') ? 'CONVERGED BUT FINAL FULL VALIDATION FAILED'
  : (lastSurvivors.length === 0 && finalValidation.status !== 'passed') ? 'CONVERGED BUT FINAL FULL VALIDATION UNAVAILABLE'
  : lastSurvivors.length === 0 ? 'CONVERGED CLEAN'
  : 'STOPPED - no new blockers (possible oscillation on remaining items)'

const efficiency = {
  criticLaneCalls: roundsRun * chunks.length * laneCount,
  verificationClaims,
  verificationVotesRequested: verificationClaims * reviewers,
  verificationOverflowClaims: verificationOverflow.length,
  unresolvedVerificationOverflowClaims: pendingVerificationOverflow.length,
  duplicateVerificationClaimsSkipped: verificationDedupSavings,
  focusedValidationRounds: fixLog.length,
  focusedValidationCommands: fixLog.reduce((n, e) => n + ((e.focusedValidation && e.focusedValidation.commands || []).filter((c) => c.status !== 'not_run').length), 0),
  finalFullValidationRuns: finalValidationEligible ? 1 : 0,
}
// ---- Phase 4: synthesize an evidence-rich report ----
phase('Report')
const report = await agent(
  'Write an evidence-rich but scannable final review report. Use these sections in order:\n' +
  '1. Verdict and confidence: explain exactly which convergence, coverage, focused-validation, and final-validation conditions passed or failed.\n' +
  '2. Scope and chunking: files/lines, chunk distribution, oversized-file risks, and critic-lane coverage.\n' +
  '3. Round-by-round trajectory table: round, lane coverage, findings, gated raw/deduped, verification claims/overflow, verified/refuted/disputed/unverified, fixes requested, and focused-test status.\n' +
  '4. Fixed by round: for EVERY fix round, list each finding id/location, what was wrong, exact change, files changed, tests added/updated, focused commands run and outcomes, and validator notes. Do not collapse this into only counts.\n' +
  '5. Final full validation: why it ran or was skipped, commands/outcomes, failures, and summary. Make clear that full-suite validation happens only here.\n' +
  '6. Resolution metrics and efficiency: addressed vs focused-validated resolved, verification calls saved by deduplication, and validation command counts.\n' +
  '7. Escalations and residual risk: fixer failure/possible partial changes, unresolved verification overflow with every finding, unresolved, unverified, disputed, unconfirmed fixes, then tracked-for-later grouped by theme.\n' +
  'Do not claim a fix is resolved unless its focused validation passed, and do not claim CONVERGED CLEAN when fixer failure, missing coverage, verification overflow, or incomplete final validation remains.\n\n' +
  'VERDICT:\n' + verdict +
  '\nSCOPE AND CHUNKS:\n' + JSON.stringify({ scope, files: scan.files.length, totalLines: scan.totalLines, perChunk, chunks: chunkSummary, oversizedFiles }) +
  '\nTRAJECTORY:\n' + JSON.stringify(trajectory) +
  '\nFIX LOG:\n' + JSON.stringify(fixLog) +
  '\nFINAL FULL VALIDATION:\n' + JSON.stringify(finalValidation) +
  '\nMETRICS:\n' + JSON.stringify({ totalAddressed, totalResolved, efficiency, coverageComplete, converged, terminationReason, limits }) +
  '\nFIXER FAILURE:\n' + JSON.stringify(fixerFailure) +
  '\nVERIFICATION OVERFLOW LEDGER:\n' + JSON.stringify(verificationOverflow) +
  '\nUNRESOLVED VERIFICATION OVERFLOW:\n' + JSON.stringify(pendingVerificationOverflow) +
  '\nUNRESOLVED:\n' + JSON.stringify(lastSurvivors) +
  '\nUNVERIFIED:\n' + JSON.stringify(unverifiedUnique) +
  '\nDISPUTED:\n' + JSON.stringify(disputedUnique) +
  '\nUNCONFIRMED FIX ROUNDS:\n' + JSON.stringify(unconfirmedFixes) +
  '\nTRACKED:\n' + JSON.stringify(trackedUnique),
  { tier: 'medium', label: 'synthesis' })

return {
  verdict, terminationReason, roundsRun, chunks: chunks.length, chunkSummary, oversizedFiles, limits,
  totalAddressed, totalResolved, totalFixed: totalResolved,
  unresolved: lastSurvivors, unverified: unverifiedUnique, disputed: disputedUnique, tracked: trackedUnique,
  verificationOverflow, verificationOverflowCount: verificationOverflow.length,
  unresolvedVerificationOverflow: pendingVerificationOverflow,
  unresolvedVerificationOverflowCount: pendingVerificationOverflow.length, fixerFailure,
  trajectory, fixLog, finalValidation, efficiency, report,
}
